with deduped as (select * from orders qualify row_number() over (partition by channel, customer_id order by amount asc, id asc) = 1) select id, customer_id, store_id, order_date, status, discount, shipping_fee, case when status rlike '^(RETURNED|SHIPPED)$' then 'EXTENDED' when status rlike '^(COMPLETED|PENDING)$' then 'GROUP_B' else 'PRIORITY' end as status_zone from deduped order by customer_id asc;
